--
-- Table structure for table `lista_chequeo_ejecutadas`
--

DROP TABLE IF EXISTS `lista_chequeo_ejecutadas`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `lista_chequeo_ejecutadas` (
  `id` int NOT NULL AUTO_INCREMENT,
  `lista_chequeo_id` int NOT NULL,
  `evaluado_id` int DEFAULT NULL,
  `usuario_id` int NOT NULL,
  `latitud` varchar(300) DEFAULT NULL,
  `longitud` varchar(300) DEFAULT NULL,
  `direccion` varchar(100) DEFAULT NULL,
  `estado` tinyint(1) NOT NULL DEFAULT '1' COMMENT '0: Cancelada; 1: Proceso; 2: Terminada',
  `fecha_realizacion` datetime NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `finished_at` datetime DEFAULT NULL,
  `observacion_general` text,
  `revisado` int DEFAULT NULL COMMENT 'Id de usuario que revisa la lista',
  PRIMARY KEY (`id`),
  KEY `ejecutadas_listachequeo_idx` (`lista_chequeo_id`),
  KEY `ejecutadas_usuario_idx` (`usuario_id`),
  KEY `lista_chequeo_ejecutadas_usuario_FK` (`revisado`),
  CONSTRAINT `ejecutadas_listachequeo` FOREIGN KEY (`lista_chequeo_id`) REFERENCES `lista_chequeo` (`id`) ON DELETE CASCADE,
  CONSTRAINT `ejecutadas_usuario` FOREIGN KEY (`usuario_id`) REFERENCES `usuario` (`id`),
  CONSTRAINT `lista_chequeo_ejecutadas_usuario_FK` FOREIGN KEY (`revisado`) REFERENCES `usuario` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB AUTO_INCREMENT=134 DEFAULT CHARSET=utf8mb3;
/*!40101 SET character_set_client = @saved_cs_client */;

