DROP TABLE IF EXISTS `lista_chequeo_encabezado`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `lista_chequeo_encabezado` (
  `id` int NOT NULL AUTO_INCREMENT,
  `fecha` tinyint(1) NOT NULL,
  `entidad_evaluada_opcion` tinyint(1) NOT NULL COMMENT '1:Asociada al evaluador o el mismo evaluador;\n2:Selecciona de una lista\n',
  `lista_chequeo_id` int NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `lcencabezado_listachequeo_idx` (`lista_chequeo_id`),
  CONSTRAINT `lcencabezado_listachequeo` FOREIGN KEY (`lista_chequeo_id`) REFERENCES `lista_chequeo` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=154 DEFAULT CHARSET=utf8mb3;
/*!40101 SET character_set_client = @saved_cs_client */;

