--
-- Table structure for table `pregunta`
--

DROP TABLE IF EXISTS `pregunta`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `pregunta` (
  `id` int NOT NULL AUTO_INCREMENT,
  `nombre` varchar(850) NOT NULL,
  `ponderado` decimal(18,2) NOT NULL,
  `categoria_id` int DEFAULT NULL,
  `orden_lista` int NOT NULL,
  `lista_chequeo_id` int NOT NULL,
  `tipo_respuesta_id` int NOT NULL,
  `permitir_noaplica` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `pregunta_listachequeo_idx` (`lista_chequeo_id`),
  KEY `pregunta_categoria_idx` (`categoria_id`),
  KEY `pregunta_tiporespuesta_idx` (`tipo_respuesta_id`),
  CONSTRAINT `pregunta_categoria` FOREIGN KEY (`categoria_id`) REFERENCES `categoria` (`id`) ON DELETE CASCADE,
  CONSTRAINT `pregunta_listachequeo` FOREIGN KEY (`lista_chequeo_id`) REFERENCES `lista_chequeo` (`id`) ON DELETE CASCADE,
  CONSTRAINT `pregunta_tiporespuesta` FOREIGN KEY (`tipo_respuesta_id`) REFERENCES `tipo_respuesta` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=11635 DEFAULT CHARSET=utf8mb3;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `pregunta`
--

LOCK TABLES `pregunta` WRITE;
/*!40000 ALTER TABLE `pregunta` DISABLE KEYS */;
