(170,'¿Se realiza monitoreos a los trabajadores sobre la temperatura y el uso correcto de los EPP de Bioseguridad?',11.00,36,11,15,2,0,'2020-07-21 19:28:18','2020-07-21 19:29:04'),
(171,'Si el colaborador presenta síntomas de infección respiratoria como: fiebre, tos, dificultad para respirar, fatiga, secreciones nasales o presenta temperaturas de 38°C o superiores. ¿Esta condición es informada inmediatamente a la EPS respectiva del trabajador?',11.00,36,12,15,2,0,'2020-07-21 19:28:31','2020-07-21 19:29:04'),
(172,'¿Se tiene establecido un protocolo de verificación de estado de salud de cada colaborador, proveedor o cliente; llevando un reporte diario de síntomas y temperatura?',11.00,36,13,15,2,0,'2020-07-21 19:28:47','2020-07-21 19:29:04'),
