(11413,'¿En las últimas 48 horas usted, además de tos constante, está presentando cualquiera de los siguientes síntomas: fiebre, fatiga, expectoración, problemas para respirar, malestar general, dolor de garganta, dolor de cabeza, escalofrío, congestión nasal, nauseas, vómito o diarrea?',17.00,2472,2,132,2,1,'2020-10-02 19:16:06','2020-10-02 19:17:20'),
