--
-- Table structure for table `venta_payu`
--

DROP TABLE IF EXISTS `venta_payu`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `venta_payu` (
  `id` int NOT NULL AUTO_INCREMENT,
  `reference_code` varchar(255) DEFAULT NULL COMMENT 'Código de referencia creado pro e-commerce',
  `transaction_state` smallint DEFAULT NULL COMMENT '4 : Transacción Aprobada\n6 : Transacción Rechazada \n7 : Transacción Pendiente \n104 : Error',
  `pol_response_code` varchar(70) DEFAULT NULL COMMENT 'Código de respuesta PAYU',
  `reference_pol` varchar(255) DEFAULT NULL COMMENT 'No Transacción generado en PAYU',
  `tx_value` decimal(14,2) DEFAULT NULL COMMENT 'Monto total',
  `tx_tax` decimal(14,2) DEFAULT NULL COMMENT 'Impuesto total',
  `buyer_email` varchar(255) DEFAULT NULL COMMENT 'Email del comprador',
  `processing_date` datetime DEFAULT NULL COMMENT 'Fecha de transacción',
  `currency` varchar(3) DEFAULT NULL COMMENT 'Moneda de pago',
  `cus` varchar(255) DEFAULT NULL COMMENT 'Código único de seguimiento banco PSE',
  `pse_bank` varchar(255) DEFAULT NULL COMMENT 'Nombre del banco PSE',
  `description` varchar(255) DEFAULT NULL COMMENT 'Descripción de la venta',
  `lap_response_code` varchar(64) DEFAULT NULL COMMENT 'Código de respuesta PAYU',
  `lap_payment_method` varchar(255) DEFAULT NULL COMMENT 'Medio de pago ',
  `lap_payment_type` varchar(255) DEFAULT NULL COMMENT 'Tipo de medio de pago ',
  `lap_transaction_state` varchar(32) DEFAULT NULL COMMENT 'Estado de la transacción ',
  `message` varchar(255) DEFAULT NULL COMMENT 'Descripción estado de transacción',
  `extra1` varchar(255) DEFAULT NULL COMMENT 'Campo adicional para mostrar descripción de la compra ',
  `extra2` varchar(255) DEFAULT NULL COMMENT 'Campo adicional para mostrar descripción de la compra ',
  `extra3` varchar(255) DEFAULT NULL COMMENT 'Campo adicional para mostrar descripción de la compra ',
  `autorization_code` varchar(12) DEFAULT NULL COMMENT 'Código de autorización',
  `merchant_address` varchar(255) DEFAULT NULL COMMENT 'Dirección del comercio - comprador ',
  `merchant_name` varchar(255) DEFAULT NULL COMMENT 'Nombre del comercio - comprador ',
  `pse_cycle` decimal(18,2) DEFAULT NULL COMMENT 'Identificador generado por PSE',
  `pse_reference1` varchar(255) DEFAULT NULL COMMENT 'Referencia PSE',
  `pse_reference2` varchar(255) DEFAULT NULL COMMENT 'Referencia PSE',
  `pse_reference3` varchar(255) DEFAULT NULL COMMENT 'Referencia PSE',
  `telephone` varchar(20) DEFAULT NULL COMMENT 'Número telefónico del comercio - comprador',
  `transaction_id` varchar(36) DEFAULT NULL COMMENT 'Identificador de la transacción',
  `trazability_code` varchar(64) DEFAULT NULL COMMENT 'Código de seguimiento del sitio del comercio',
  `tx_administrative_fee` decimal(18,2) DEFAULT NULL COMMENT 'Valor tarifa administrativa',
  `tx_tax_administrative_fee` decimal(18,2) DEFAULT NULL COMMENT 'Valor del impuesto de la tarifa administrativa',
  `tx_tax_administrative_fee_return_base` decimal(18,2) DEFAULT NULL COMMENT 'Valor de la base administrativa para la devolución de impuestos',
  `action_code_description` varchar(255) DEFAULT NULL COMMENT 'Descripción de código de respuesta visanet PERÚ',
  `cc_holder` varchar(150) DEFAULT NULL COMMENT 'Nombre de la tarjeta habiente PERÚ',
  `cc_number` varchar(255) DEFAULT NULL COMMENT 'Nombre de la tarjeta de crédito PERÚ',
  `processing_date_time` datetime DEFAULT NULL COMMENT 'Fecha y hora del procesamiento de la venta PERÚ',
  `request_number` varchar(9) DEFAULT NULL COMMENT 'Número de la orden mas identificador de la transacción PERÚ',
  `id_cuenta_principal` int NOT NULL,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `fk_cuenta_principal_payu_idx` (`id_cuenta_principal`),
  CONSTRAINT `fk_cuenta_principal_payu` FOREIGN KEY (`id_cuenta_principal`) REFERENCES `cuenta_principal` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;
/*!40101 SET character_set_client = @saved_cs_client */;

